await bash('cd /workspace && cat > /tmp/render_check.py <<'EOF'
import sys; sys.path.insert(0, '.')
from invoice import render_invoice
from tests.test_invoice import ORDER_A, ORDER_B
for name, order in (("invoice_a", ORDER_A), ("invoice_b", ORDER_B)):
    rendered = render_invoice(order)
    golden = open(f"tests/golden/{name}.txt").read()
    if rendered != golden:
        print(f"--- {name} DIFF ---")
        for rl, gl in zip(rendered.split("\n"), golden.split("\n")):
            mark = " " if rl == gl else "*"
            print(f"{mark} code|{rl}|")
            if mark == "*": print(f"{mark} gold|{gl}|")
EOF
/opt/venv/bin/python /tmp/render_check.py')
